  "description": "Fetch the full content of one entity in the workspace.\n\n...",
  "name": "read",
  "parameters": {
    "properties": {
      "entity_ref": {
        "anyOf": [{"additionalProperties": {}, "type": "object"}, {"type": "string"}],
        "description": "typed handle, shape `{kind, id, parent?}`. Examples:...",
        "title": "Entity Ref"
      },
      "scope": ...
    },
    "required": ["entity_ref"],
```

